852					if err != nil {
853						return nil, err
854					}
855					return c.GetMirror(ctx, coreapi.GetMirrorParams{MirrorId: mirrorID})
856				}
857				// A ULID carries no cluster coordinate, so it can only be looked up
858				// on the active context's core. A clone URL names its cluster — dial
859				// the core fronting that cluster (discovered from its well-known and
860				// authenticated with the matching local context, the same path
861				// create/remove use), so the lookup works when the mirror lives in a
862				// federation other than the active login instead of failing with
863				// "no mirror matching".
864				if looksLikeULID(ref) {
