879	// resolveMirrorRef turns a mirror reference into its ULID. A ULID passes
880	// through unchanged. Otherwise the ref is parsed as an entire:// clone URL and
881	// resolved by listing the caller-visible mirrors for that (cluster, provider,
882	// owner) and matching the repo — there is no get-by-coords endpoint, only
883	// GetMirror(ULID). The clone URL carries the cluster, so the match is
884	// unambiguous even when the same upstream is mirrored on several clusters.
885	func resolveMirrorRef(ctx context.Context, c *coreapi.Client, ref string) (string, error) {
886		if looksLikeULID(ref) {
887			return ref, nil
888		}
889		clusterHost, provider, owner, repo, err := parseMirrorCloneURL(ref)
890		if err != nil {
891			return "", badMirrorRefErr(err)
892		}
893		mirrors, err := fetchAllPages(ctx, func(ctx context.Context, cursor string) ([]coreapi.Mirror, string, error) {
894			params := coreapi.ListMirrorsParams{
895				Cluster:  coreapi.NewOptString(clusterHost),
896				Provider: coreapi.NewOptString(provider),
897				Owner:    coreapi.NewOptString(owner),
898			}
899			if cursor != "" {
900				params.PageToken = coreapi.NewOptString(cursor)
901			}
902			out, lerr := c.ListMirrors(ctx, params)
903			if lerr != nil {
904				return nil, "", lerr
905			}
906			return out.Mirrors, out.NextPageToken.Or(""), nil
907		})
908		if err != nil {
909			return "", err
910		}
911		// ListMirrors has no repo filter, so the owner-scoped page is matched on
912		// repo client-side. Owner/repo are stored lowercase; EqualFold guards
913		// against a differently-cased clone URL.
914		for _, m := range mirrors {
915			if strings.EqualFold(m.Repo, repo) {
916				return m.MirrorId, nil
917			}
918		}
919		return "", noMirrorErr(ref)
920	}
921	
922	// parseMirrorCloneURL decomposes an entire:// mirror clone URL into its
923	// coordinates:
924	//
925	//	entire://<clusterHost>/gh/<owner>/<repo>
926	//
927	// Only the github ("gh") provider path is recognized — the only provider
928	// mirrors support today. The cluster host is validated the same way the
929	// create/remove verbs validate it, so a host carrying URL metacharacters is
930	// rejected at the boundary rather than flowing into the list filter.
931	func parseMirrorCloneURL(raw string) (clusterHost, provider, owner, repo string, err error) {
932		u, perr := url.Parse(raw)
933		if perr != nil || u.Scheme != "entire" {
934			return "", "", "", "", fmt.Errorf("%q is not an entire:// clone URL", raw)
935		}
936		parts := strings.Split(strings.Trim(u.Path, "/"), "/")
937		if len(parts) != 3 || parts[0] != "gh" {
938			return "", "", "", "", fmt.Errorf("%q must be entire://<cluster>/gh/<owner>/<repo>", raw)
939		}

